content.css:
/***********************************************************
 * BFusion Intro Visual — centered hero + one-shot splash
 ***********************************************************/
.bfh-root {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
  background: var(--bfh-bg, #FFFFFF);
  color: var(--bfh-text, #0F172A);
  font-family: var(--bfh-font, "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif);
  box-sizing: border-box;
}
.bfh-root *,
.bfh-root *::before,
.bfh-root *::after {
  box-sizing: border-box;
}
.bfh-root *:focus-visible {
  outline: 2px solid var(--bfh-accent, #E8612A);
  outline-offset: 2px;
  border-radius: 4px;
}
/* Respect prefers-reduced-motion (suite-wide rule). */
@media (prefers-reduced-motion: reduce) {
  .bfh-root *,
  .bfh-root *::before,
  .bfh-root *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}
/***********************************************************
 * Stage (hero) — centered, ambient brand glow background
 ***********************************************************/
.bfh-stage {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: radial-gradient(circle at 22% 28%, rgba(232, 97, 42, 0.1) 0%, transparent 45%), radial-gradient(circle at 78% 72%, rgba(31, 42, 68, 0.1) 0%, transparent 50%), linear-gradient(180deg, var(--bfh-bg, #FFFFFF) 0%, var(--bfh-surface, #F8FAFC) 100%);
}
.bfh-stage::before {
  content: "";
  position: absolute;
  inset: -10%;
  background: radial-gradient(circle at 50% 50%, rgba(232, 97, 42, 0.05) 0%, transparent 40%);
  animation: bfh-ambient 9s ease-in-out infinite alternate;
  pointer-events: none;
}
.bfh-card {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 16px;
  max-width: 760px;
}
/***********************************************************
 * Logo
 ***********************************************************/
.bfh-logo {
  width: 132px;
  height: 80px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  overflow: hidden;
  background: var(--bfh-accent, #E8612A);
  box-shadow: 0 10px 28px rgba(232, 97, 42, 0.25);
  margin-bottom: 4px;
  animation: bfh-logo-in 700ms cubic-bezier(0.2, 0.8, 0.2, 1) 80ms both;
}
.bfh-logo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  user-select: none;
}
/***********************************************************
 * Sequenced text
 ***********************************************************/
.bfh-title {
  margin: 0;
  font-family: var(--bfh-font, "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif);
  font-size: var(--bfh-title-fs, 44px);
  line-height: 1.1;
  font-weight: 700;
  letter-spacing: -0.015em;
  color: var(--bfh-text, #0F172A);
  animation: bfh-fade-up 700ms cubic-bezier(0.2, 0.8, 0.2, 1) 520ms both;
}
.bfh-subtitle {
  font-family: var(--bfh-font, "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif);
  font-size: var(--bfh-subtitle-fs, 18px);
  line-height: 1.5;
  font-weight: 500;
  color: var(--bfh-muted, #475569);
  max-width: 60ch;
  animation: bfh-fade-up 700ms cubic-bezier(0.2, 0.8, 0.2, 1) 1000ms both;
}
.bfh-tagline {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-top: 12px;
  padding: 8px 18px;
  border: 1px solid var(--bfh-border, #E2E8F0);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.65);
  backdrop-filter: blur(4px);
  font-family: var(--bfh-font, "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif);
  font-size: var(--bfh-tagline-fs, 13px);
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--bfh-navy, #1F2A44);
  animation: bfh-fade-up 700ms cubic-bezier(0.2, 0.8, 0.2, 1) 1500ms both;
}
.bfh-tagline__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--bfh-accent, #E8612A);
  box-shadow: 0 0 0 0 var(--bfh-accent, #E8612A);
  animation: bfh-pulse 2.4s ease-out 2000ms infinite;
}
/***********************************************************
 * Splash overlay — one-shot
 ***********************************************************/
.bfh-splash {
  position: absolute;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  user-select: none;
  background: radial-gradient(circle at 22% 28%, rgba(232, 97, 42, 0.12) 0%, transparent 45%), radial-gradient(circle at 78% 72%, rgba(31, 42, 68, 0.1) 0%, transparent 50%), linear-gradient(180deg, #FFFFFF 0%, var(--bfh-surface, #F8FAFC) 100%);
  animation: bfh-fade-in 240ms ease-out both;
}
.bfh-splash--leaving {
  animation: bfh-fade-out 320ms ease-in forwards;
  pointer-events: none;
}
.bfh-splash__inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 14px;
  padding: 40px 56px 28px;
  background: #FFFFFF;
  border-radius: 14px;
  border-top: 4px solid var(--bfh-accent, #E8612A);
  box-shadow: 0 24px 70px rgba(15, 23, 42, 0.16);
  max-width: 540px;
}
.bfh-splash__logo {
  width: 156px;
  height: 96px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  overflow: hidden;
  background: var(--bfh-accent, #E8612A);
  box-shadow: 0 8px 24px rgba(232, 97, 42, 0.32);
  animation: bfh-logo-in 700ms cubic-bezier(0.2, 0.8, 0.2, 1) 80ms both;
}
.bfh-splash__logo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  user-select: none;
}
.bfh-splash__title {
  font-family: var(--bfh-font, "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif);
  font-size: 30px;
  font-weight: 700;
  color: var(--bfh-text, #0F172A);
  line-height: 1.15;
  letter-spacing: -0.01em;
  animation: bfh-fade-up 700ms cubic-bezier(0.2, 0.8, 0.2, 1) 520ms both;
}
.bfh-splash__subtitle {
  font-family: var(--bfh-font, "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif);
  font-size: 15px;
  font-weight: 500;
  color: var(--bfh-muted, #475569);
  line-height: 1.5;
  max-width: 44ch;
  animation: bfh-fade-up 700ms cubic-bezier(0.2, 0.8, 0.2, 1) 1000ms both;
}
.bfh-splash__tagline {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
  padding: 6px 14px;
  border-radius: 999px;
  border: 1px solid var(--bfh-border, #E2E8F0);
  background: rgba(248, 250, 252, 0.9);
  font-family: var(--bfh-font, "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--bfh-navy, #1F2A44);
  animation: bfh-fade-up 700ms cubic-bezier(0.2, 0.8, 0.2, 1) 1500ms both;
}
.bfh-splash__tagline-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--bfh-accent, #E8612A);
  box-shadow: 0 0 0 0 var(--bfh-accent, #E8612A);
  animation: bfh-pulse 2.4s ease-out 2100ms infinite;
}
.bfh-splash__bar {
  width: 220px;
  height: 2px;
  margin-top: 16px;
  background: var(--bfh-border, #E2E8F0);
  border-radius: 2px;
  overflow: hidden;
}
.bfh-splash__bar-fill {
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, var(--bfh-accent, #E8612A) 0%, var(--bfh-navy, #1F2A44) 100%);
  transform: translateX(-100%);
  animation: bfh-bar 1200ms ease-out 200ms forwards;
}
/***********************************************************
 * License badge (suite standard)
 ***********************************************************/
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 30;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: var(--bfh-font, "Space Grotesk", "Inter", "Segoe UI", system-ui, sans-serif);
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
/***********************************************************
 * Keyframes
 ***********************************************************/
@keyframes bfh-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes bfh-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@keyframes bfh-fade-up {
  from {
    opacity: 0;
    transform: translate3d(0, 14px, 0);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}
@keyframes bfh-logo-in {
  0% {
    opacity: 0;
    transform: translate3d(0, 16px, 0) scale(0.82);
  }
  60% {
    opacity: 1;
    transform: translate3d(0, -3px, 0) scale(1.03);
  }
  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
  }
}
@keyframes bfh-bar {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(0);
  }
}
@keyframes bfh-pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(232, 97, 42, 0.55);
  }
  70% {
    box-shadow: 0 0 0 10px rgba(232, 97, 42, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(232, 97, 42, 0);
  }
}
@keyframes bfh-ambient {
  from {
    transform: translate3d(-4%, -2%, 0) scale(1);
    opacity: 0.85;
  }
  to {
    transform: translate3d(4%, 2%, 0) scale(1.06);
    opacity: 1;
  }
}
/***********************************************************
 * Narrow viewport — scale down hero
 ***********************************************************/
@media (max-width: 600px) {
  .bfh-title {
    font-size: clamp(24px, 6vw, var(--bfh-title-fs, 44px));
  }
  .bfh-subtitle {
    font-size: clamp(13px, 3.5vw, var(--bfh-subtitle-fs, 18px));
  }
  .bfh-logo {
    width: 110px;
    height: 66px;
  }
}
